def prefix_averages(S):
    A, total = [], 0
    for j, x in enumerate(S):
        total += x
        A.append(total / (j + 1))
    return A

dsaf-english-ruler.solution:
def draw_ruler(num_inches, major_length):
    lines = []
    def tick(length, label=''):
        lines.append('-' * length + (' ' + label if label else ''))
    def interval(c):
        if c > 0:
            interval(c - 1)
            tick(c)
            interval(c - 1)
    tick(major_length, '0')
    for j in range(1, num_inches + 1):
        interval(major_length - 1)
        tick(major_length, str(j))
    return lines

dsaf-recursive-binary-search.solution:
def binary_search(data, target):
    def search(low, high):
        if low > high:
            return -1
        mid = (low + high) // 2
        if data[mid] == target:
            return mid
        if target < data[mid]:
            return search(low, mid - 1)
        return search(mid + 1, high)
    return search(0, len(data) - 1)

