dsaf-dynamic-array.solution:
class DynamicArray:
    def __init__(self):
        self._n = 0
        self._cap = 1
        self._A = [None] * self._cap

    def _resize(self, c):
        B = [None] * c
        for i in range(self._n):
            B[i] = self._A[i]
        self._A, self._cap = B, c

    def append(self, x):
        if self._n == self._cap:
            self._resize(2 * self._cap)
        self._A[self._n] = x
        self._n += 1

    def insert(self, k, x):
        if self._n == self._cap:
            self._resize(2 * self._cap)
        for j in range(self._n, k, -1):
            self._A[j] = self._A[j - 1]
        self._A[k] = x
        self._n += 1

    def get(self, k):
        if 0 <= k < self._n:
            return self._A[k]
        return None

    def set(self, k, x):
        if 0 <= k < self._n:
            self._A[k] = x
            return True
        return False

    def pop(self):
        if self._n == 0:
            return None
        self._n -= 1
        x = self._A[self._n]
        self._A[self._n] = None
        if self._cap > 1 and self._n < self._cap // 4:
            self._resize(self._cap // 2)
        return x

    def size(self):
        return self._n

    def capacity(self):
        return self._cap

dsaf-caesar-cipher.solution:
def caesar(message, shift, mode):
    if mode == "decrypt":
        shift = -shift
    out = []
    for c in message:
        if 'A' <= c <= 'Z':
            out.append(chr((ord(c) - 65 + shift) % 26 + 65))
        elif 'a' <= c <= 'z':
            out.append(chr((ord(c) - 97 + shift) % 26 + 97))
        else:
            out.append(c)
    return ''.join(out)

