class CircularQueue:
    def __init__(self, k):
        self._data = [None] * k
        self._front = 0
        self._size = 0

    def enqueue(self, x):
        if self._size == len(self._data):
            return False
        avail = (self._front + self._size) % len(self._data)
        self._data[avail] = x
        self._size += 1
        return True

    def dequeue(self):
        if self._size == 0:
            return None
        x = self._data[self._front]
        self._data[self._front] = None
        self._front = (self._front + 1) % len(self._data)
        self._size -= 1
        return x

    def first(self):
        return None if self._size == 0 else self._data[self._front]

    def last(self):
        if self._size == 0:
            return None
        return self._data[(self._front + self._size - 1) % len(self._data)]

    def is_empty(self):
        return self._size == 0

    def is_full(self):
        return self._size == len(self._data)

    def size(self):
        return self._size

