dsaf-tree-traversals.solution:
from collections import deque

class Solution:
    def traversals(self, root):
        pre, ino, post, lvl = [], [], [], []
        def dfs(p):
            if p is None:
                return
            pre.append(p.val)
            dfs(p.left)
            ino.append(p.val)
            dfs(p.right)
            post.append(p.val)
        dfs(root)
        Q = deque([root] if root else [])
        while Q:
            p = Q.popleft()
            lvl.append(p.val)
            if p.left: Q.append(p.left)
            if p.right: Q.append(p.right)
        return [pre, ino, post, lvl]

